import { useEffect, useState } from "react";
import axios from "axios";
import { toast } from "react-toastify";

function Cart() {
  const [cart, setCart] = useState([]);

  // Load cart
  useEffect(() => {
    const savedCart = JSON.parse(localStorage.getItem("cart")) || [];

    setCart(savedCart);
  }, []);

  // Group items
  const groupedCart = Object.values(
    cart.reduce((acc, item) => {
      if (!acc[item._id]) {
        acc[item._id] = {
          ...item,
          qty: 1,
        };
      } else {
        acc[item._id].qty += 1;
      }

      return acc;
    }, {}),
  );

  // Total
  const total = groupedCart.reduce(
    (sum, item) => sum + item.price * item.qty,
    0,
  );

  // Place order
  const placeOrder = () => {
    const user = JSON.parse(sessionStorage.getItem("user"));

    if (!user) {
      alert("Please login first");
      return;
    }

    axios
      .post("http://localhost:5000/orders", {
        userEmail: user.email,
        items: groupedCart,
        total,
      })
      .then(() => {
        toast.success(`Order placed successfully! ₹${total}`);

        localStorage.removeItem("cart");

        setCart([]);
      })
      .catch((err) => {
        console.log(err);

        alert("Failed to place order");
      });
  };

  // Clear cart
  const clearCart = () => {
    toast.info("Cart cleared");
    localStorage.removeItem("cart");

    setCart([]);
  };

  // Increase qty
  const increaseQty = (item) => {
    const updatedCart = [...cart, item];

    localStorage.setItem("cart", JSON.stringify(updatedCart));

    setCart(updatedCart);
  };

  // Decrease qty
  const decreaseQty = (item) => {
    const updatedCart = [...cart];

    const index = updatedCart.findIndex((i) => i._id === item._id);

    if (index !== -1) {
      updatedCart.splice(index, 1);
    }

    localStorage.setItem("cart", JSON.stringify(updatedCart));

    setCart(updatedCart);
  };

  // Remove item completely
  const removeItem = (itemId) => {
    const updatedCart = cart.filter((item) => item._id !== itemId);

    localStorage.setItem("cart", JSON.stringify(updatedCart));

    setCart(updatedCart);
  };

  return (
    <div
      style={{
        padding: "30px",
        background: "#f5f5f5",
        minHeight: "100vh",
      }}
    >
      <h1>Your Cart</h1>

      {groupedCart.length === 0 ? (
        <p>Cart is empty</p>
      ) : (
        <>
          {groupedCart.map((item) => (
            <div
              key={item._id}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                border: "1px solid #ddd",
                padding: "20px",
                marginBottom: "20px",
                borderRadius: "15px",
                background: "#fff",
                boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
              }}
            >
              <div>
                <h3>{item.name}</h3>

                <p>Price: ₹{item.price}</p>

                {/* Quantity Controls */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "10px",
                    marginTop: "10px",
                  }}
                >
                  <button
                    onClick={() => decreaseQty(item)}
                    style={styles.qtyBtn}
                  >
                    -
                  </button>

                  <span
                    style={{
                      fontWeight: "bold",
                    }}
                  >
                    {item.qty}
                  </span>

                  <button
                    onClick={() => increaseQty(item)}
                    style={styles.qtyBtn}
                  >
                    +
                  </button>
                </div>

                {/* Subtotal */}
                <p
                  style={{
                    marginTop: "10px",
                    fontWeight: "bold",
                  }}
                >
                  Subtotal: ₹{item.price * item.qty}
                </p>

                {/* Remove */}
                <button
                  onClick={() => removeItem(item._id)}
                  style={styles.removeBtn}
                >
                  Remove
                </button>
              </div>

              <img
                src={item.image}
                alt={item.name}
                style={{
                  width: "120px",
                  height: "120px",
                  objectFit: "cover",
                  borderRadius: "10px",
                }}
              />
            </div>
          ))}

          <h2>Total: ₹{total}</h2>

          <button onClick={placeOrder} style={styles.orderBtn}>
            Place Order
          </button>

          <button onClick={clearCart} style={styles.clearBtn}>
            Clear Cart
          </button>
        </>
      )}
    </div>
  );
}

const styles = {
  qtyBtn: {
    width: "35px",
    height: "35px",
    border: "none",
    borderRadius: "50%",
    cursor: "pointer",
    fontSize: "18px",
    fontWeight: "bold",
  },

  removeBtn: {
    marginTop: "10px",
    padding: "8px 15px",
    border: "none",
    borderRadius: "8px",
    background: "red",
    color: "#fff",
    cursor: "pointer",
  },

  orderBtn: {
    padding: "12px 25px",
    border: "none",
    borderRadius: "10px",
    cursor: "pointer",
    marginRight: "10px",
    fontSize: "16px",
  },

  clearBtn: {
    padding: "12px 25px",
    border: "none",
    borderRadius: "10px",
    cursor: "pointer",
    fontSize: "16px",
  },
};

export default Cart;
